using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
public partial class TimelineEditorOperations
{
    private readonly TimelineCanvasOperations _timelineCanvas=new();private readonly ActorInspectorOperations _inspector=new();
    public void refresh(Control owner)
    {
        var canvas=owner.Get("canvas").As<Control>();var horizontal=owner.Get("h_scroll").As<HScrollBar>();if(canvas==null||horizontal==null)return;var model=Model(owner);_timeline.validate_focus(model);var restored=new Settings();string section=model.Get("selected_section_id").AsString(),focus=model.Get("focused_actor_id").AsString(),displayed=owner.Get("_displayed_section_id").AsString();bool changed=displayed!=section;var sections=owner.Get("_timeline_section_states").AsGodotDictionary();if(changed){if(displayed.Length>0)sections[displayed]=new Settings{["x"]=canvas.Get("scroll_time"),["y"]=canvas.Get("scroll_rows"),["zoom_x"]=canvas.Get("pixels_per_second"),["zoom_y"]=canvas.Get("row_height"),["cursor"]=canvas.Get("playhead"),["snap"]=canvas.Get("snap_enabled")};restored=sections.GetValueOrDefault(section,new Settings()).AsGodotDictionary();if(restored.Count>0){canvas.Set("pixels_per_second",restored["zoom_x"]);canvas.Set("row_height",restored["zoom_y"]);canvas.Set("playhead",restored["cursor"]);canvas.Set("snap_enabled",restored["snap"]);owner.Get("x_zoom").As<HSlider>().SetValueNoSignal(canvas.Get("pixels_per_second").AsDouble());owner.Get("y_zoom").As<HSlider>().SetValueNoSignal(canvas.Get("row_height").AsDouble());owner.Get("snap_button").As<CheckButton>().SetPressedNoSignal(canvas.Get("snap_enabled").AsBool());}}var vertical=owner.Get("v_scroll").As<VScrollBar>();if(changed||owner.Get("_displayed_focus_id").AsString()!=focus){owner.Set("_displayed_section_id",section);owner.Set("_displayed_focus_id",focus);_timelineCanvas.cancel_drag(canvas);if(changed&&restored.Count==0){horizontal.Value=0;vertical.Value=0;}}var clip=_timeline.selected_clip(model);var start=owner.Get("start_input").As<SpinBox>();var end=owner.Get("end_input").As<SpinBox>();start.Editable=clip!=null;end.Editable=clip!=null;start.SetValueNoSignal(clip?.Get("start_time").AsDouble()??0);end.SetValueNoSignal(clip!=null?clip.Get("start_time").AsDouble()+clip.Get("duration").AsDouble():0);var history=model.Get("history").As<UndoRedo>();var undo=owner.Get("undo_button").As<Button>();undo.Disabled=!history.HasUndo();owner.Get("redo_button").As<Button>().Disabled=!history.HasRedo();undo.TooltipText=history.HasUndo()?"Undo "+history.GetCurrentActionName():"Nothing to undo";double time=Time(owner);owner.Get("time_label").As<Label>().Text=$"  ◷  {(int)(time/60):D2}:{time%60:00.00}  ";double endTime=Math.Max(60,time+15);foreach(var value in _timeline.visible_clips(model)){var item=value.As<Resource>();endTime=Math.Max(endTime,item.Get("start_time").AsDouble()+item.Get("duration").AsDouble()+15);}var clips=Clips(owner);for(int i=0;i<clips.Count;i++)if(_timeline.hidden_clip_obstructs_view(model,i)){var item=clips[i].As<Resource>();endTime=Math.Max(endTime,item.Get("start_time").AsDouble()+item.Get("duration").AsDouble()+15);}horizontal.Page=Math.Max(1,(canvas.Size.X-140)/canvas.Get("pixels_per_second").AsDouble());horizontal.MaxValue=Math.Max(endTime,horizontal.Page);vertical.Page=Math.Max(1,canvas.Size.Y-34);double height=canvas.Get("row_height").AsDouble();vertical.MaxValue=Math.Max(vertical.Page,_timelineCanvas.display_layer_count(canvas)*height);var recording=canvas.Get("recording_preview").AsGodotDictionary();if(recording.Count>0)vertical.MaxValue=Math.Max(vertical.MaxValue,(recording["layer"].AsInt32()+2)*height);if(restored.Count>0){horizontal.Value=restored["x"].AsDouble();vertical.Value=restored["y"].AsDouble();canvas.Set("scroll_time",horizontal.Value);canvas.Set("scroll_rows",vertical.Value);}if(changed)evaluate_runtimes(owner);canvas.QueueRedraw();model.Set("playhead_time",canvas.Get("playhead"));var editor=owner.Get("keyframe_editor").As<Control>();if(editor!=null&&editor.Get("lanes").As<Control>() is Control lanes){lanes.QueueRedraw();editor.Get("ruler").As<Control>().QueueRedraw();}var inspector=owner.Get("inspector").As<Control>();if(GodotObject.IsInstanceValid(inspector))_inspector.refresh(inspector!);owner.Call("_update_breadcrumbs");update_idle_hint(owner);
    }
    public void update_idle_hint(Control owner){var canvas=owner.Get("canvas").As<Control>();if(canvas==null)return;var model=Model(owner);var selected=model.Get("selected_ids").AsGodotArray();var shortcuts=new List<string>{Playing(owner)?"Space Pause":"Space Play","R Record mic",canvas.Get("split_tool").AsBool()?"V Select tool":"B Split tool"};if(selected.Count==0){shortcuts.Add("Shift+A Add actor");shortcuts.Add("Drag empty area Box select");if(Clips(owner).Count>0)shortcuts.Add("Ctrl+A Select all");}else{shortcuts.Add("Delete/Backspace Delete");shortcuts.Add("Ctrl+D Duplicate");shortcuts.Add("Ctrl+C Copy");var primary=_timeline.selected_actor(model);shortcuts.Add(primary!=null&&primary.Get("id").AsString()==model.Get("focused_actor_id").AsString()?"F Go up one level":"F Focus primary actor");if(selected.Count>1)shortcuts.Add("P Parent to primary");if(_timeline.selected_actors(model).Any(value=>value.As<Resource>().Get("parent_id").AsString().Length>0))shortcuts.Add("Shift+P Unparent");if(selected.Count<Clips(owner).Count)shortcuts.Add("Ctrl+A Select all");}if(model.Get("focused_actor_id").AsString().Length>0){shortcuts.Add("Alt+← Back to parent");shortcuts.Add("Alt+Home Section view");}if(owner.Get("_actor_clipboard").AsGodotArray().Count>0)shortcuts.Add("Ctrl+V Paste at playhead");var history=model.Get("history").As<UndoRedo>();if(history.HasUndo())shortcuts.Add("Ctrl+Z Undo");if(history.HasRedo())shortcuts.Add("Ctrl+Shift+Z Redo");owner.Get("hints").AsGodotObject().Call("set_idle",string.Join("  •  ",shortcuts));}
}
